# @@ keep letters and digits, in lower case
def normalize(s) {
    return join("", [lower(py_c3) for py_c3 in s if isalnum(py_c3)])
}
# @@ compare with the reverse
def is_palindrome(s) {
    t = normalize(s)
    return t == t[::-1]
}
# @@ compare from both ends
def is_palindrome_two_ends(s) {
    t = normalize(s)
    i = 0
    j = len(t) - 1
    while i < j {
        if t[i] != t[j] {
            return false
        }
        i = py_int(i + 1)
        j = py_int(j - 1)
    }
    return true
}
# @@ try some phrases
PHRASES = ["A man, a plan, a canal: Panama", "Was it a car or a cat I saw?", "No lemon, no melon", "Hello, world", "Été"]
for py_i4 to len(PHRASES) {
    p = PHRASES[py_i4]
    verdict = ("yes" if is_palindrome(p) else "no")
    print(fmt(verdict, "3"), normalize(p))
}
# @@ checks
for py_i5 to len(PHRASES) {
    p = PHRASES[py_i5]
    if not (is_palindrome(p) == is_palindrome_two_ends(p)) {
        stop("AssertionError")
    }
}
